import {
  Box,
  Container,
  createTheme,
  Grid,
  Typography,
  useMediaQuery,
} from "@mui/material";
import React, { useEffect, useState } from "react";
import MapChart from "src/views/common/mapchartComponent";
import mapImg from "../../../assets/images/mapImg.png";
import { axiosInstance } from "src/network/adapter";
import { ApiEndpoints } from "src/network/endpoints";
import { toastError, toastSuccess } from "src/utils/utils";

const ContactUs = () => {
  const contactDetails = [
    {
      title: "Customer Success",
      description: "Our friendly team is here to lend a hand!",
      contactInfo: " support@dw-its.com",
    },
    {
      title: "Sales",
      description: "Have you a question? Reach out, we're here to assist!",
      contactInfo: "  sales@dw-its.com",
    },
    {
      title: "Time",
      description: "From Sunday to Thursday",
      contactInfo: "(8 AM - 4 PM)",
    },
  ];
  const [contactUsData, setContactUsData] = useState([]);
  const fetchContactUsData = () => {
    axiosInstance
      .get(ApiEndpoints.CONTACTUS.list)
      .then((response) => {
        const responseData = response.data.data;
        const activeData = responseData.filter(
          (item) => item.status === "active"
        );
        setContactUsData(activeData);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        // setLoading(false);
      });
  };
  useEffect(() => {
    fetchContactUsData();
  }, []);
  const theme = createTheme();
  const isMobile = useMediaQuery(theme.breakpoints.up("md"));
  return (
    <>
      <Box>
        <Container
          maxWidth={"xl"}
          sx={{ px: { xs: 5, sm: 10, lg: 15, xl: 20 } }}
        >
          <Grid container rowGap={{ xs: 6, sm: 12 }}>
            <Grid
              item
              xs={12}
              sx={{
                display: "flex",
                flexDirection: "column",
                alignItems: "center",
                gap: { xs: 2, sm: 4 },
              }}
            >
              <Typography
                sx={{
                  fontSize: { xs: "26px", sm: "44px", md: "54px", lg: "64px" },
                  lineHeight: {
                    xs: "34px",
                    sm: "54px",
                    md: "64px",
                    lg: "83px",
                  },
                  fontWeight: 500,
                  color: "#201D28",
                }}
              >
                Contact us
              </Typography>
              <Typography
                sx={{
                  fontSize: { xs: "14px", sm: "18px" },
                  lineHeight: { xs: "26px", sm: "28px" },
                  fontWeight: 500,
                  color: "#69668E",
                }}
              >
                Our main office in Sultanate Of Oman, Muscat
              </Typography>
            </Grid>
            <Grid
              item
              container
              sx={{
                border: "1.5px solid #E2E5EA",
                borderRadius: "15px",
                px: { xs: 10, lg: 15 },
                py: { xs: 10, lg: 10 },
              }}
            >
              <Grid item xs={12}>
                {isMobile && (
                  <Box>
                    <MapChart />
                  </Box>
                )}
              </Grid>
              <Grid item container xs={12}>
                {contactUsData.map((item, index) => (
                  <Grid item xs={12} md={4} key={index}>
                    <Box
                      sx={{
                        display: "flex",
                        flexDirection: "column",
                        gap: { xs: 3, md: 5 },
                      }}
                    >
                      <Box
                        sx={{
                          display: "flex",
                          flexDirection: "column",
                          gap: { md: 1 },
                        }}
                      >
                        <Typography
                          sx={{
                            fontSize: { xs: "18px", md: "20px" },
                            lineHeight: { md: "30px" },
                            fontWeight: 700,
                            color: "#000000",
                            textAlign: "center",
                          }}
                        >
                          {item.title}
                        </Typography>
                        <Typography
                          sx={{
                            fontSize: "16px",
                            lineHeight: "24px",
                            fontWeight: 500,
                            color: "#8795AA",
                            textAlign: "center",
                          }}
                        >
                          <div
                            // className="blog_____content"
                            dangerouslySetInnerHTML={{
                              __html: item.description,
                            }}
                          />
                        </Typography>
                      </Box>

                      <Typography
                        sx={{
                          fontSize: "16px",
                          lineHeight: "24px",
                          fontWeight: 500,
                          color: "#602DE1",
                          textAlign: "center",
                        }}
                      >
                        {" "}
                        {item.email ? item.email : item.time}
                      </Typography>
                    </Box>
                  </Grid>
                ))}
              </Grid>
            </Grid>
          </Grid>
        </Container>
      </Box>
    </>
  );
};

export default ContactUs;
